PAGE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spaceport · Mission Control</title>
<style>
:root{color-scheme:dark;font:16px system-ui;background:#070d18;color:#e3eefc}*{box-sizing:border-box}body{max-width:1200px;margin:auto;padding:34px 22px;background:radial-gradient(ellipse at 70% 0,#15344866,transparent 65%)}h1{font-size:clamp(30px,5vw,49px);letter-spacing:-2px;margin:10px 0}h2{font-size:20px;margin:0 0 18px}h3{font-size:15px;color:#abc2db}.eyebrow{letter-spacing:3px;color:#66ead2;font-size:11px}header{display:flex;align-items:center;justify-content:space-between;gap:15px;padding-bottom:24px;border-bottom:1px solid #223348;margin-bottom:24px}p,small{color:#9aafc8;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}article,.panel{padding:24px;border:1px solid #263b50;background:#0e1929e8;border-radius:20px}.wide{grid-column:1/-1}button,input,select,textarea{font:inherit;border:1px solid #36516d;background:#101f32;color:#e3eefc;border-radius:9px;padding:11px 13px;max-width:100%}button{cursor:pointer;margin:3px}button:hover{border-color:#69ebd3;background:#1b3949}button.primary{background:#6cebd1;color:#052b2b;font-weight:650;border:0}button.danger{color:#ffb3bd}button:disabled{opacity:.4;cursor:wait}input,textarea{width:100%}input[type=range]{padding:0;accent-color:#6cebd1}label{display:block;font-size:13px;color:#b4c8de;margin:14px 0}label input,label select,label textarea{margin-top:7px}#password{max-width:420px}.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.pill{padding:7px 12px;border:1px solid #38536a;border-radius:30px;font-size:12px;color:#80ecd5}.hidden{display:none!important}#message{padding:12px 0;min-height:46px;color:#82efd7}a{color:#79dce8}.team{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:15px 0}.person{border:1px solid #34455b;border-radius:12px;padding:13px 8px;text-align:center}.person b{font-size:23px;display:block}.event{padding:10px 0;border-bottom:1px solid #273a50}.event b{display:block;font-size:17px}.event small{font-size:13px}footer{font-size:12px;color:#738aa4;margin:30px 0}.slider{display:grid;grid-template-columns:1fr 50px;gap:15px;align-items:center}.slider label{grid-column:1/-1;margin-bottom:0}#login{max-width:650px;margin:60px auto}.buttons{margin-top:10px}@media(max-width:700px){.grid{grid-template-columns:1fr}header{align-items:flex-start}.team{grid-template-columns:repeat(2,1fr)}article{padding:20px}}
</style><header><div><div class=eyebrow>SPACEPORT / YOUR DESK, IN ORBIT</div><h1>Mission Control</h1><small>Spaceagon · Waveshare · Calendar · Calls</small></div><div class=row><span id=link class=pill>LOCKED</span><button id=lock class=hidden>Lock</button></div></header>
<section id=login class=panel><h2>Welcome aboard</h2><p>Enter your separate administrator password. It stays in this tab’s memory and is cleared when you lock or close the page.</p><form id=loginForm><label>Administrator password<input id=password type=password autocomplete=off required></label><button class=primary>Unlock Mission Control</button></form></section>
<div id=message role=status aria-live=polite></div><main id=app class="grid hidden">
<article><div class=eyebrow>COMMUNICATIONS</div><h2>3CX &amp; your team</h2><div id=own></div><div id=team class=team></div><div class=row><button data-dnd=true>Enable DND</button><button data-dnd=false>Available</button></div><h3>Speed dial</h3><div id=dials class=row></div><small>Calling rings your own extension first. Calls always require a deliberate press.</small></article>
<article><div class=eyebrow>FLIGHT PLAN</div><h2>Your calendar</h2><div id=calendar></div><button id=calendarRefresh>Refresh calendar</button><small> Titles and times only. Private events say Busy.</small></article>
<article><div class=eyebrow>SPACEAGON</div><h2>Lights &amp; focus</h2><small>Sliders show proposed values, not device readings. Changes apply when the badge next checks in. Commands expire after one minute.</small><div id=badgeSliders></div><label>Focus sand direction<select id=focusDirection><option value=0>Down</option><option value=1>Left</option><option value=2>Up</option><option value=3>Right</option></select></label><div class=buttons><button data-badge=focus_start>Start / resume focus</button><button data-badge=focus_pause>Pause focus</button><button data-badge=focus_reset>Reset focus</button></div><label>Theme<select id=theme><option value="auto">Automatic / seasonal</option><option value="original">Original</option><option value="christmas">Christmas</option><option value="easter">Easter</option><option value="anniversary">Anniversary</option><option value="birthday_self">My birthday</option><option value="birthday_partner">Partner birthday</option><option value="cyberpunk">Cyberpunk</option><option value="lcars">LCARS</option><option value="kitty">Cute cat</option><option value="photo">Photo</option><option value="noir">Noir</option><option value="ocean">Ocean</option><option value="retro">Retro</option></select></label><button id=setTheme>Apply theme</button><label>Clock face<select id=clock><option value="original">Original</option><option value="celestial">Celestial</option><option value="tokyoflash">Tokyo Code</option><option value="radar">Orbital Radar</option><option value="flip">Flip Station</option><option value="analogue">Clean Analogue</option><option value="corpus">Corpus / Time Eater</option><option value="haute_celestial">Celestial Atelier</option><option value="neon_orrery">Neon Orrery</option><option value="mondaine">Mondaine</option><option value="great_british_railways">Great British Railways</option></select></label><button id=setClock>Apply clock</button></article>
<article><div class=eyebrow>WAVESHARE</div><h2>Sound &amp; display</h2><div class=row><button data-wave=mute>Mute</button><button data-wave=unmute>Sound on</button><button data-wave=silence>Silence alert</button><button data-wave=dismiss>Clear local notice</button></div><div id=waveSliders></div><div class=buttons><button data-wave=page>Next screen</button><button data-wave=test>Test chime</button><button data-wave=demo>Visual demo</button><button data-wave=live>Return to live</button></div><small>Presence detection still controls whether audio is allowed.</small></article>
<article class=wide><div class=eyebrow>INCOMING SIGNAL</div><h2>Send a notification</h2><form id=noticeForm><div class=grid><label>Title<input id=noticeTitle value="Spaceport online" required maxlength=80></label><label>Priority<select id=noticePriority><option value=3>Normal</option><option value=4>High</option><option value=5>Urgent — stays on screen</option></select></label></div><label>Message<textarea id=noticeBody rows=2 maxlength=320>Mission Control is ready.</textarea></label><button class=primary>Send to Waveshare &amp; Spaceagon LEDs</button></form></article>
<article class=wide><h2>Number book</h2><p>Confirm or correct “Likely” caller matches for incoming and outgoing calls.</p><a href=/lookup target=_blank rel=noopener>Open number book →</a><p><small>The number book retains its separate review password.</small></p></article></main><footer>Authenticated controls · No mailbox password or API keys are returned to this page · Calendar updates every five minutes</footer>
<script>
const $=id=>document.getElementById(id);let token='',state=null,polling=false;
function message(s,bad=false){$('message').textContent=s;$('message').style.color=bad?'#ffb3bd':'#82efd7'}
async function api(path,data){const r=await fetch('/admin/api/'+path,{method:data===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'X-Spaceport-Admin':'1','Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})});let j=await r.json();if(!r.ok)throw Error(r.status===401?'Administrator password not accepted.':j.message||j.error||'Request failed');return j}
function node(tag,text){let e=document.createElement(tag);e.textContent=text;return e}
async function refresh(){if(!token||polling)return;polling=true;try{state=await api('state');$('link').textContent=state.demo?'PREVIEW':state.connected?'LIVE':'PBX OFFLINE';$('own').textContent='Your status: '+(state.own?.presence?.state||'Unknown');$('team').replaceChildren();for(const m of state.team||[]){let box=node('div','');box.className='person';box.append(node('b',m.name),node('small',m.state));$('team').append(box)}$('dials').replaceChildren();for(const target of state.controls?.targets||state.controls?.speed_dials||[]){let b=node('button',target.label);b.disabled=!state.controls.call;b.onclick=()=>call(target);$('dials').append(b)}$('calendar').replaceChildren();let c=state.calendar||{};if(!c.available)$('calendar').append(node('p',c.enabled?'Calendar unavailable — check connection.':'Calendar not connected.'));else if(!c.events.length)$('calendar').append(node('p','Clear skies — no upcoming events this week.'));else for(const e of c.events){let d=node('div','');d.className='event';d.append(node('b',e.title),node('small',e.all_day?new Date(e.start*1000).toLocaleDateString('en-GB')+' · All day':new Date(e.start*1000).toLocaleString('en-GB',{timeZone:'Europe/London',weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+'–'+new Date(e.end*1000).toLocaleTimeString('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit'})));$('calendar').append(d)}}finally{polling=false}}
async function perform(path,data){try{let result=await api(path,data);message(result.status==='queued'?'Queued for device — expires in 60 seconds.':'Request accepted.');await refresh()}catch(e){message(e.message,true)}}
async function call(t){if(!confirm('Call '+t.label+' from your extension?'))return;await perform('call',{target:t.id,session_id:state.controls.session_id,request_id:crypto.randomUUID().replaceAll('-','')})}
function device(device,action,value){return perform('device',{device,action,...(value===undefined?{}:{value})})}
function sliders(container,device,items){for(const [action,title,max,initial] of items){let wrap=node('div','');wrap.className='slider';let label=node('label',title),input=document.createElement('input'),out=node('output',initial+'%');input.type='range';input.min=action==='brightness'?5:0;input.max=max;input.value=initial;input.setAttribute('aria-label',title);input.oninput=()=>out.textContent=input.value+'%';input.onchange=()=>deviceChange();function deviceChange(){deviceFn(device,action,Number(input.value))}wrap.append(label,input,out);$(container).append(wrap)}}const deviceFn=device;
sliders('badgeSliders','spaceagon',[['ring_brightness','Badge LEDs',100,25],['eeh_brightness','EEH LEDs',100,4],['matrix_brightness','Matrix call brightness',100,100],['focus_brightness','Focus sand brightness',100,35]]);sliders('waveSliders','waveshare',[['volume','Ringtone volume',75,20],['priority_volume','Priority volume',75,35],['brightness','Screen brightness',100,50]]);
$('loginForm').onsubmit=async e=>{e.preventDefault();token=$('password').value;$('password').value='';try{await refresh();$('login').classList.add('hidden');$('app').classList.remove('hidden');$('lock').classList.remove('hidden');message('Welcome aboard.')}catch(e){token='';message(e.message,true)}};
$('lock').onclick=()=>{token='';state=null;$('app').classList.add('hidden');$('login').classList.remove('hidden');$('lock').classList.add('hidden');$('team').replaceChildren();$('dials').replaceChildren();$('calendar').replaceChildren();$('own').textContent='';$('link').textContent='LOCKED';message('Locked.')};
document.querySelectorAll('[data-wave]').forEach(b=>b.onclick=()=>device('waveshare',b.dataset.wave));document.querySelectorAll('[data-badge]').forEach(b=>b.onclick=()=>device('spaceagon',b.dataset.badge));document.querySelectorAll('[data-dnd]').forEach(b=>b.onclick=()=>perform('dnd',{enabled:b.dataset.dnd==='true',session_id:state.controls.session_id,request_id:crypto.randomUUID().replaceAll('-','')}));$('focusDirection').onchange=()=>device('spaceagon','focus_direction',Number($('focusDirection').value));$('setTheme').onclick=()=>device('spaceagon','theme',$('theme').value);$('setClock').onclick=()=>device('spaceagon','clock',$('clock').value);$('calendarRefresh').onclick=()=>perform('calendar_refresh',{});$('noticeForm').onsubmit=e=>{e.preventDefault();perform('notify',{title:$('noticeTitle').value,body:$('noticeBody').value,priority:Number($('noticePriority').value),type:'info',ttl_seconds:300})};setInterval(()=>refresh().catch(e=>message(e.message,true)),5000);
</script></html>'''
